vector<string> display(vector<json_object> search) {
  vector<string> result;
  for (auto& video : search) {
    string videoTitle;
    string videoGenre;
    string videoReleaseYear;
    string videoLink;
    string videoDescription;
    string videoAdditional;
    string reason1, reason2, reason3, reason4;

    // Extract video details from video object
    videoTitle = video.title;
    videoGenre = video.genre;
    videoReleaseYear = video.release_year;
    videoLink = video.link;
    videoDescription = video.description;
    videoAdditional = video_additional;

    // Create JSON objects for each video
    result.emplace_back(
      "video_info",
      {"
        title: {0}
        genre: {1}
        release_year: {2}
        reason: "Video details"
      "}
    );
    result.emplace_back(
      "video_search",
      {"
        title: {0}
        genre: {1}
        release_year: {2}
        reason: "Video search results"
      "}
    );
    result.emplace_back(
      "video_metadata",
      {"
        title: {0}
        genre: {1}
        release_year: {2}
        reason: "Video metadata"
      "}
    );
    result.emplace_back(
      "video_details",
      {"
        title: {0}
        genre: {1}
        release_year: {2}
        reason: "Video details"
      "}
    );
  }
  return result;
}
